const express = require('express');
const { LRUCache } = require('lru-cache');

const app = express();
app.use(express.json());

const pendingAuthCache = new LRUCache({
  max: 5000,
  ttl: 1000 * 60 * 5 // 5 minutes
});

app.post('/oauth/token/exchange', (req, res) => {
  const { authorizationCode, clientId } = req.body;

  // Lookup pending authorization state using authorization code
  const authRecord = pendingAuthCache.get(authorizationCode);
  if (!authRecord) {
    return res.status(400).json({ error: 'Invalid or expired authorization code' });
  }

  // Ensure requesting client matches the authorized client in the cached record
  if (authRecord.clientId !== clientId) {
    return res.status(401).json({ error: 'Client identification mismatch' });
  }

  pendingAuthCache.delete(authorizationCode);
  return res.json({
    access_token: authRecord.generatedAccessToken,
    token_type: 'Bearer',
    expires_in: 3600,
    user_id: authRecord.userId,
    scope: authRecord.scope
  });
});

module.exports = app;
